class Solution:
    def numMovesStonesII(self, stones):
        stones.sort()
        n = len(stones)
        mx = (stones[-1] - stones[0] + 1 - n) - min(stones[1] - stones[0], stones[-1] - stones[-2])
        import bisect
        mn = n
        for i in range(n):
            j = bisect.bisect_right(stones, stones[i] + n - 1)
            cnt = j - i
            if cnt == n - 1 and stones[j - 1] - stones[i] == n - 2:
                mn = min(mn, 2)
            else:
                mn = min(mn, n - cnt)
        return [mn, mx]

