class Solution {
    public int[] numMovesStonesII(int[] stones) {
        Arrays.sort(stones);
        int n = stones.length;
        int mx = (stones[n-1] - stones[0] + 1 - n) - Math.min(stones[1] - stones[0], stones[n-1] - stones[n-2]);
        int mn = n;
        for (int i = 0; i < n; i++) {
            int j = upperBound(stones, stones[i] + n - 1);
            int cnt = j - i;
            if (cnt == n - 1 && stones[j-1] - stones[i] == n - 2) mn = Math.min(mn, 2);
            else mn = Math.min(mn, n - cnt);
        }
        return new int[]{mn, mx};
    }
    private int upperBound(int[] a, long x) {
        int lo = 0, hi = a.length;
        while (lo < hi) { int mid = (lo + hi) / 2; if (a[mid] <= x) lo = mid + 1; else hi = mid; }
        return lo;
    }
}

